/**
 * tests/legacy_cloud_format.test.js
 *
 * Vitest verification suite for legacy cloud document format and counter semantics:
 * 1. Legacy cloud documents (dataVersion 1, 2, 14, 1000) generated by old createCloudPayload
 * 2. Real SyncManager + MemorySyncAdapter flows with dataVersion 14 (signIn, syncNow, flushSave)
 * 3. Mixed documents & two-device order problem (monotonicity, commutativity, idempotence)
 * 4. Backups: old-format, new-format, and dataFormat 2 claiming files containing legacy keys
 * 5. Cross-device sync scenario where fake cloud already holds legacy dataVersion 14 document
 */

import { describe, it, expect, beforeEach, vi } from 'vitest';
import path from 'path';
import { execSync } from 'child_process';
import SyncMergePolicy from '../sync/merge_policy.js';
import { SyncManager, STATES } from '../sync/sync_manager.js';
import MemorySyncAdapter from '../sync/memory_adapter.js';
import { validateBackupData } from './unit_fixes.test.js';

const categoriesJson = execSync(`node "${path.join(__dirname, '../scripts/extract_categories_ast.js')}"`, { encoding: 'utf8' });
const CATEGORIES = JSON.parse(categoriesJson);

describe('1. Legacy Cloud Documents with Realistic Counters (Item 1 & 5)', () => {
  const versions = [1, 2, 14, 1000];

  for (const v of versions) {
    it(`validates and losslessly merges legacy cloud doc with dataVersion ${v}`, () => {
      // Equivalent to document produced by v1.12 createCloudPayload
      const berufeCat = CATEGORIES.find(c => c.id === 'berufe');
      const obstCat = CATEGORIES.find(c => c.id === 'obst');
      const berufe0Id = berufeCat.words[0].id;
      const berufe1Id = berufeCat.words[1].id;
      const obst0Id = obstCat.words[0].id;

      const legacyDoc = {
        schemaVersion: 1,
        dataVersion: v,
        updatedAt: '2026-10-10T10:00:00.000Z',
        progress: {
          berufe: {
            mcq: { unlocked: 5, counts: { '0': 2, '1': 3 } }
          },
          obst: {
            mcq: { unlocked: 5, counts: { '0': 5 } }
          }
        },
        stats: { current: 3, longest: 5, totalAnswered: 10, totalCorrect: 9 },
        starred: ['berufe_0', 'obst_0'],
        srs: {
          'berufe_0': { box: 1, lastDate: '2026-10-01', nextDate: '2026-10-03' }
        },
        dailyGoal: { target: 20 }
      };

      // Validation must succeed
      const val = SyncMergePolicy.validateCloudDocument(legacyDoc, CATEGORIES);
      expect(val.valid).toBe(true);
      expect(val.error).toBeUndefined();

      // Local id-keyed data
      const localData = {
        progress: {
          berufe: {
            mcq: { unlocked: 5, counts: { [berufe0Id]: 4, [berufe1Id]: 1 } }
          }
        },
        stats: { current: 4, longest: 6, totalAnswered: 15, totalCorrect: 14 },
        starred: [berufe0Id],
        srs: {
          [berufe0Id]: { box: 2, lastDate: '2026-10-05', nextDate: '2026-10-10' }
        },
        dailyGoal: { target: 25 }
      };

      const merged = SyncMergePolicy.mergeFullUserData(localData, legacyDoc, CATEGORIES);

      // Verify counter semantics: max(loc, cld) + 1
      expect(merged.dataVersion).toBe(v + 1);

      // Verify ID keys only (no numeric keys)
      expect(merged.progress.berufe.mcq.counts['0']).toBeUndefined();
      expect(merged.progress.berufe.mcq.counts['1']).toBeUndefined();
      expect(merged.progress.obst.mcq.counts['0']).toBeUndefined();

      // Verify exact word identity via CATEGORIES
      expect(merged.progress.berufe.mcq.counts[berufe0Id]).toBe(4); // max(4, 2)
      expect(merged.progress.berufe.mcq.counts[berufe1Id]).toBe(3); // max(1, 3)
      expect(merged.progress.obst.mcq.counts[obst0Id]).toBe(5);

      // Verify starred
      expect(merged.starred).toContain(berufe0Id);
      expect(merged.starred).toContain(obst0Id);
      expect(merged.starred).not.toContain('berufe_0');
      expect(merged.starred).not.toContain('obst_0');

      // Verify SRS
      expect(merged.srs[berufe0Id]).toBeDefined();
      expect(merged.srs[berufe0Id].box).toBe(2); // Local had higher box and newer date
      expect(merged.srs['berufe_0']).toBeUndefined();
    });
  }
});

describe('2. REAL SyncManager + MemorySyncAdapter flows with dataVersion 14 (Item 2)', () => {
  const berufeCat = CATEGORIES.find(c => c.id === 'berufe');
  const berufe0Id = berufeCat.words[0].id;
  const berufe1Id = berufeCat.words[1].id;

  let sharedStore;
  let adapter;
  let localState;
  let sm;

  beforeEach(() => {
    sharedStore = new Map();
    const legacyCloudDoc = {
      schemaVersion: 1,
      dataVersion: 14,
      updatedAt: '2026-10-10T10:00:00.000Z',
      progress: {
        berufe: { mcq: { unlocked: 5, counts: { '0': 3 } } }
      },
      stats: { current: 5, longest: 10, totalAnswered: 50, totalCorrect: 45 },
      starred: ['berufe_0'],
      srs: { 'berufe_0': { box: 2, lastDate: '2026-10-08', nextDate: '2026-10-15' } },
      dailyGoal: { target: 20 }
    };
    sharedStore.set('test-user-123', legacyCloudDoc);

    adapter = new MemorySyncAdapter({ store: sharedStore });

    localState = {
      progress: {
        berufe: { mcq: { unlocked: 5, counts: { [berufe0Id]: 2, [berufe1Id]: 4 } } }
      },
      stats: { current: 2, longest: 5, totalAnswered: 20, totalCorrect: 18 },
      starred: [berufe0Id],
      srs: { [berufe0Id]: { box: 1, lastDate: '2026-10-09', nextDate: '2026-10-12' } },
      dailyGoal: { target: 25 }
    };

    globalThis.CATEGORIES = CATEGORIES;
    globalThis.confirm = () => true;
    globalThis.exportBackup = () => '{}';

    sm = new SyncManager({
      adapter,
      policy: SyncMergePolicy,
      debounceMs: 50,
      localStateProvider: {
        getLocalData: () => localState,
        applyLocalData: (d) => {
          if (d.progress) localState.progress = d.progress;
          if (d.stats) localState.stats = d.stats;
          if (d.starred) localState.starred = d.starred;
          if (d.srs) localState.srs = d.srs;
          if (d.dailyGoal) localState.dailyGoal = d.dailyGoal;
        }
      }
    });
  });

  it('syncOnSignIn successfully merges legacy dataVersion 14 cloud document', async () => {
    sm.init();
    await sm.signIn();

    expect(sm.state).toBe(STATES.SYNCED);
    expect(sm.lastError).toBeNull();

    const savedCloud = sharedStore.get('test-user-123');
    expect(savedCloud).toBeDefined();
    // Counter incremented monotonically
    expect(savedCloud.dataVersion).toBeGreaterThanOrEqual(15);
    // Keys migrated to stable IDs
    expect(savedCloud.progress.berufe.mcq.counts[berufe0Id]).toBe(3); // max(2, 3)
    expect(savedCloud.progress.berufe.mcq.counts[berufe1Id]).toBe(4);
    expect(savedCloud.progress.berufe.mcq.counts['0']).toBeUndefined();
    expect(savedCloud.starred).toEqual([berufe0Id]);
    expect(savedCloud.srs[berufe0Id]).toBeDefined();
    expect(savedCloud.srs['berufe_0']).toBeUndefined();

    // Subsequent launches / syncOnSignIn do not fail or lose progress
    await sm.syncOnSignIn();
    expect(sm.state).toBe(STATES.SYNCED);
    expect(sm.lastError).toBeNull();
  });

  it('syncNow runs full cycle with legacy cloud doc, uploading id keys with max+1 counter', async () => {
    sm.init();
    await sm.signIn();

    // Local user learns more
    localState.progress.berufe.mcq.counts[berufe0Id] = 8;
    sm.notifyChange();

    await sm.syncNow();
    expect(sm.state).toBe(STATES.SYNCED);
    expect(sm.lastError).toBeNull();

    const savedCloud = sharedStore.get('test-user-123');
    expect(savedCloud.progress.berufe.mcq.counts[berufe0Id]).toBe(8);
    expect(savedCloud.dataVersion).toBeGreaterThanOrEqual(16);
  });

  it('flushSave runs read-merge-write without error or retry loop', async () => {
    sm.init();
    await sm.signIn();

    localState.progress.berufe.mcq.counts[berufe1Id] = 9;
    sm.notifyChange();

    await sm.flushSave();
    expect(sm.state).toBe(STATES.SYNCED);
    expect(sm.lastError).toBeNull();

    const savedCloud = sharedStore.get('test-user-123');
    expect(savedCloud.progress.berufe.mcq.counts[berufe1Id]).toBe(9);
  });

  it('malformed cloud document is rejected, never overwritten, and keeps non-transient error', async () => {
    // Malformed document: non-numeric junk in counts
    const corruptDoc = {
      schemaVersion: 1,
      dataVersion: 14,
      progress: {
        berufe: { mcq: { unlocked: 5, counts: { 'malformed_key_junk': 1 } } }
      }
    };
    const corruptStore = new Map();
    corruptStore.set('test-user-123', corruptDoc);

    const corruptSm = new SyncManager({
      adapter: new MemorySyncAdapter({ store: corruptStore }),
      policy: SyncMergePolicy,
      localStateProvider: {
        getLocalData: () => localState,
        applyLocalData: () => {}
      }
    });

    corruptSm.init();
    await corruptSm.signIn();

    expect(corruptSm.state).toBe(STATES.ERROR);
    expect(corruptSm.lastError).toContain('بيانات السحابة غير صالحة');

    // Cloud document was NEVER overwritten!
    const storeAfter = corruptStore.get('test-user-123');
    expect(storeAfter).toEqual(corruptDoc);
  });
});

describe('3. MIXED Documents and Two-Device Order Problem (Item 3)', () => {
  const berufeCat = CATEGORIES.find(c => c.id === 'berufe');
  const w0 = berufeCat.words[0].id;
  const w1 = berufeCat.words[1].id;

  it('Device N (new IDs) and Device O (legacy keys, higher counter) merge correctly without data loss', () => {
    // Device N uploaded format 2
    const docN = {
      schemaVersion: 1,
      dataVersion: 15,
      progress: {
        berufe: { mcq: { unlocked: 5, counts: { [w0]: 4, [w1]: 2 } } }
      },
      stats: { current: 5, longest: 10, totalAnswered: 50, totalCorrect: 45 },
      starred: [w0],
      srs: { [w0]: { box: 2, lastDate: '2026-10-05', nextDate: '2026-10-12' } },
      dailyGoal: { target: 20 }
    };

    // Device O (old code, not updated yet) uploaded legacy numeric keys with higher counter
    const docO = {
      schemaVersion: 1,
      dataVersion: 18,
      progress: {
        berufe: { mcq: { unlocked: 5, counts: { '0': 5, '1': 1 } } }
      },
      stats: { current: 6, longest: 11, totalAnswered: 60, totalCorrect: 55 },
      starred: ['berufe_0', 'berufe_1'],
      srs: {
        'berufe_0': { box: 3, lastDate: '2026-10-08', nextDate: '2026-10-20' },
        'berufe_1': { box: 1, lastDate: '2026-10-07', nextDate: '2026-10-10' }
      },
      dailyGoal: { target: 25, updatedAt: '2026-10-08T00:00:00Z' }
    };

    // Device N reads O
    const mergedNO = SyncMergePolicy.mergeFullUserData(docN, docO, CATEGORIES);
    // Device O reading N
    const mergedON = SyncMergePolicy.mergeFullUserData(docO, docN, CATEGORIES);

    // Commutativity
    expect(mergedNO.progress).toEqual(mergedON.progress);
    expect(mergedNO.stats).toEqual(mergedON.stats);
    expect(mergedNO.starred).toEqual(mergedON.starred);
    expect(mergedNO.srs).toEqual(mergedON.srs);
    expect(mergedNO.dailyGoal).toEqual(mergedON.dailyGoal);

    // Monotonicity and no data loss
    expect(mergedNO.dataVersion).toBe(19); // max(15, 18) + 1
    expect(mergedNO.progress.berufe.mcq.counts[w0]).toBe(5); // max(4, 5)
    expect(mergedNO.progress.berufe.mcq.counts[w1]).toBe(2); // max(2, 1)
    expect(mergedNO.starred).toEqual([w0, w1]);
    expect(mergedNO.srs[w0].box).toBe(3);
    expect(mergedNO.srs[w1].box).toBe(1);

    // No numeric or legacy keys remain
    expect(mergedNO.progress.berufe.mcq.counts['0']).toBeUndefined();
    expect(mergedNO.progress.berufe.mcq.counts['1']).toBeUndefined();
    expect(mergedNO.starred).not.toContain('berufe_0');
    expect(mergedNO.srs['berufe_0']).toBeUndefined();
  });

  it('Mixed document containing both legacy keys and ID keys in the same document is handled idempotently', () => {
    const mixedDoc = {
      progress: {
        berufe: {
          mcq: {
            unlocked: 5,
            counts: {
              '0': 3,
              [w0]: 5 // same word as 0, but higher count
            }
          }
        }
      },
      starred: ['berufe_0', w0],
      srs: {
        'berufe_0': { box: 1, lastDate: '2026-10-01' },
        [w0]: { box: 2, lastDate: '2026-10-05' }
      }
    };

    const migrated = SyncMergePolicy.migrateLegacyUserData(mixedDoc, CATEGORIES);

    expect(migrated.progress.berufe.mcq.counts[w0]).toBe(5);
    expect(migrated.progress.berufe.mcq.counts['0']).toBeUndefined();
    expect(migrated.starred).toEqual([w0]);
    expect(migrated.srs[w0].box).toBe(2);

    // Idempotent
    const reMigrated = SyncMergePolicy.migrateLegacyUserData(migrated, CATEGORIES);
    expect(reMigrated).toEqual(migrated);
  });
});

describe('4. Backups: Old, New, and dataFormat 2 with Legacy Keys (Item 4)', () => {
  it('old-format backup without dataFormat validates and imports cleanly', () => {
    const oldBackup = {
      version: 1,
      progress: {
        obst: { mcq: { unlocked: 3, counts: { '0': 5 } } }
      },
      starred: ['obst_0'],
      srs: { 'obst_0': { box: 1 } }
    };
    const val = validateBackupData(oldBackup, CATEGORIES);
    expect(val.valid).toBe(true);

    const migrated = SyncMergePolicy.migrateLegacyUserData(oldBackup, CATEGORIES);
    expect(migrated.dataFormat).toBe(2);
    expect(migrated.progress.obst.mcq.counts['obst.apfel']).toBe(5);
    expect(migrated.progress.obst.mcq.counts['0']).toBeUndefined();
  });

  it('new-format backup with dataFormat 2 and ID keys validates and imports cleanly', () => {
    const newBackup = {
      version: 2,
      dataFormat: 2,
      progress: {
        obst: { mcq: { unlocked: 3, counts: { 'obst.apfel': 5 } } }
      },
      starred: ['obst.apfel'],
      srs: { 'obst.apfel': { box: 1 } }
    };
    const val = validateBackupData(newBackup, CATEGORIES);
    expect(val.valid).toBe(true);

    const migrated = SyncMergePolicy.migrateLegacyUserData(newBackup, CATEGORIES);
    expect(migrated.progress.obst.mcq.counts['obst.apfel']).toBe(5);
  });

  it('backup claiming dataFormat 2 but containing legacy keys validates and imports cleanly', () => {
    const deceptiveBackup = {
      version: 2,
      dataFormat: 2,
      progress: {
        obst: { mcq: { unlocked: 3, counts: { '0': 5 } } }
      },
      starred: ['obst_0'],
      srs: { 'obst_0': { box: 1 } }
    };
    const val = validateBackupData(deceptiveBackup, CATEGORIES);
    expect(val.valid).toBe(true);

    const migrated = SyncMergePolicy.migrateLegacyUserData(deceptiveBackup, CATEGORIES);
    expect(migrated.progress.obst.mcq.counts['obst.apfel']).toBe(5);
    expect(migrated.progress.obst.mcq.counts['0']).toBeUndefined();
    expect(migrated.starred).toEqual(['obst.apfel']);
    expect(migrated.srs['obst.apfel']).toBeDefined();
  });
});

describe('6. Cross-Device Legacy Cloud Scenario with Real Classes (Item 6)', () => {
  it('Device A syncs against legacy cloud doc (dataVersion 14); Device B syncs and ends identical', async () => {
    const cloudStore = new Map();
    const legacyCloudDoc = {
      schemaVersion: 1,
      dataVersion: 14,
      updatedAt: '2026-10-10T12:00:00.000Z',
      progress: {
        berufe: { mcq: { unlocked: 5, counts: { '0': 4 } } },
        obst: { mcq: { unlocked: 5, counts: { '0': 3 } } }
      },
      stats: { current: 5, longest: 10, totalAnswered: 50, totalCorrect: 48 },
      starred: ['berufe_0', 'obst_0'],
      srs: { 'berufe_0': { box: 2, lastDate: '2026-10-08', nextDate: '2026-10-15' } },
      dailyGoal: { target: 25 }
    };
    cloudStore.set('test-user-123', legacyCloudDoc);

    const adapterA = new MemorySyncAdapter({ store: cloudStore });
    const adapterB = new MemorySyncAdapter({ store: cloudStore });

    let stateA = { progress: {}, stats: {}, starred: [], srs: {}, dailyGoal: { target: 20 } };
    let stateB = { progress: {}, stats: {}, starred: [], srs: {}, dailyGoal: { target: 20 } };

    const smA = new SyncManager({
      adapter: adapterA,
      policy: SyncMergePolicy,
      localStateProvider: {
        getLocalData: () => stateA,
        applyLocalData: (d) => { Object.assign(stateA, d); }
      }
    });

    const smB = new SyncManager({
      adapter: adapterB,
      policy: SyncMergePolicy,
      localStateProvider: {
        getLocalData: () => stateB,
        applyLocalData: (d) => { Object.assign(stateB, d); }
      }
    });

    globalThis.CATEGORIES = CATEGORIES;
    globalThis.confirm = () => true;
    globalThis.exportBackup = () => '{}';

    // Device A signs in
    smA.init();
    await smA.signIn();

    expect(smA.state).toBe(STATES.SYNCED);

    // Verify cloud has been migrated to ID keys
    const cloudAfterA = cloudStore.get('test-user-123');
    expect(cloudAfterA.dataVersion).toBeGreaterThanOrEqual(15);
    expect(cloudAfterA.progress.berufe.mcq.counts['berufe.arzt']).toBe(4);
    expect(cloudAfterA.progress.berufe.mcq.counts['0']).toBeUndefined();
    expect(cloudAfterA.progress.obst.mcq.counts['obst.apfel']).toBe(3);
    expect(cloudAfterA.progress.obst.mcq.counts['0']).toBeUndefined();

    // Device B signs in
    smB.init();
    await smB.signIn();

    expect(smB.state).toBe(STATES.SYNCED);

    // Both devices now have the same progress
    expect(stateA.progress.berufe.mcq.counts['berufe.arzt']).toBe(4);
    expect(stateB.progress.berufe.mcq.counts['berufe.arzt']).toBe(4);
    expect(stateA.progress).toEqual(stateB.progress);
    expect(stateA.starred).toEqual(stateB.starred);
    expect(stateA.srs).toEqual(stateB.srs);
  });
});
